[package]
name = "type-core"
version = "0.1.0"
description = "Framework-free core for the Type notes app: notes/front-matter, profiles (working folders), security, recordings + transcription queue, handwriting OCR, Apple Notes import, git sync, and local-network sync. Consumed by the Tauri shell and the React Native FFI crate."
edition = "2021"

[lib]
name = "type_core"

[dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = "1"
git2 = { version = "0.20", features = ["vendored-openssl"] }
base64 = "0.22"
reqwest = { version = "0.12", default-features = false, features = ["blocking", "json", "rustls-tls"] }
uuid = { version = "1", features = ["v7"] }
time = { version = "0.3", features = ["formatting", "macros", "parsing"] }
argon2 = "0.5"
chacha20poly1305 = { version = "0.10", features = ["std"] }
zeroize = "1.8"
